"""Bounded field batching of the existing conservative clearance queries.

Every source sample is compared with every other sample using the established
weighted-distance formula. Sorting independently within each query finds the
same minimum without a separate field evaluation context per sample. Larger
tables retain the original evaluator by default. The opt-in tiled variant
batches complete queries with bounded temporary storage at all valid sizes;
no samples or geometry checks are lost.
"""
import bpy
from . import curved_clearance_nodes as clearance

c = clearance.c
MAX_PAIRS = 1048576
TILE_PAIRS = 262144


def build(*, preserve_breaks=False, exact_mouths=False, curvature_limits=False,
          directional=False, intervals=False, all_intervals=False, zero_depth_rays=False,
          tiled=False):
    name = 'Prochitecture Streets / Batched profile clearance v1'
    if preserve_breaks:
        name += ' / Knots'
    if exact_mouths:
        name += ' / Exact mouths'
    if curvature_limits:
        name += ' / Curvature limit'
    if directional:
        name += ' / Directional'
    if intervals:
        assert directional
        name += ' / Intervals'
    if all_intervals:
        assert intervals
        name += ' / All intervals'
    if zero_depth_rays:
        name += ' / Directed static curb'
    if tiled:
        name += ' / Tiled queries v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    g.socket('Geometry', 'NodeSocketGeometry')
    g.socket('Input Valid', 'NodeSocketBool')
    g.socket('Margin', 'NodeSocketFloat', default=.025)
    g.socket('Geometry', 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    inp = g.node('NodeGroupInput')
    src = inp.outputs['Geometry']
    count = c._count(g, src)
    margin = c.V(g, inp.outputs['Margin'])
    valid = c.V(g, inp.outputs['Input Valid'])*g.math('GREATER_THAN',count,.5)*g.math('LESS_THAN',count,clearance.MAX_SAMPLES+.5)
    valid = valid*g.math('GREATER_THAN',margin,0.)*g.math('LESS_THAN',margin,.25)
    within = 1. if tiled else g.math('LESS_THAN',count*count,MAX_PAIRS+.5)
    # Moving the nonnegative nominal multiplier inside the pair reduction
    # preserves its minimum. Malformed negative/nonfinite widths must retain
    # the previous evaluator's exact behavior instead of using that identity.
    nominal = c.named(g,'st_cg_nominal')
    within = within*c._stat(g,src,(1.-g.math('LESS_THAN',nominal,0.))*
                            g.math('LESS_THAN',g.math('ABSOLUTE',nominal),1e30))
    index = c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    safe_count = g.math('MAXIMUM',count,1.)
    start = 0.; rows = count
    if tiled:
        # Batch complete queries, never a subset of their peers. This bounds
        # temporary pair geometry while avoiding one evaluation context per
        # query beyond the old whole-table memory limit. Every query retains
        # the same minimum over every peer, in the original output order.
        capacity = g.math('MAXIMUM',g.math('FLOOR',g.math('DIVIDE',TILE_PAIRS,safe_count)),1.)
        ri = g.node('GeometryNodeRepeatInput','Bounded batches of complete clearance queries')
        ro = g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro)
        iterations = g.math('CEIL',count/capacity)
        g.bind(c.choose(g,valid*within,iterations,0,'INT'),ri.inputs['Iterations'])
        start = c.V(g,ri.outputs['Iteration'])*capacity
        rows = g.math('MINIMUM',capacity,count-start)
    query = g.math('FLOOR',index/safe_count)
    if tiled: query = query+start
    other = g.math('MODULO',index,safe_count)
    pairs = c._line(g,c.choose(g,valid*within,rows*count,2,'INT'))
    pairs = g.setpos(pairs,c._sample(g,src,g.position(),other,'FLOAT_VECTOR'))
    for key,kind in (('owner','INT'),('t','FLOAT')):
        pairs = c._store(g,pairs,'st_cg_'+key,c._read(g,src,'st_cg_'+key,other,kind),kind)
    point = c._vec(g,c._sample(g,src,g.position(),query,'FLOAT_VECTOR'))
    distance = c._length(g,c._sub(c._vec(g,g.position()),point))
    own = c._read(g,src,'st_cg_nominal',query)
    other_width = c._read(g,src,'st_cg_nominal',other)
    owner = c._read(g,src,'st_cg_owner',query,'INT')
    candidate = distance*own/g.math('MAXIMUM',own+other_width,1e-8)
    shared = clearance._same_mouth(g,src,owner,c._read(g,src,'st_cg_t',query)) if exact_mouths else None
    if shared is not None:
        candidate = c.choose(g,shared,own,candidate)
    eligible = 1.-g.math('COMPARE',owner,c.named(g,'st_cg_owner','INT'))
    candidate = c.choose(g,eligible,candidate,1e8)
    if directional:
        candidate = clearance._directional_cap(g,src,point,
            c._vec(g,c._read(g,src,'st_cg_normal',query,'FLOAT_VECTOR')),
            own,owner,other_width,shared,zero_depth_rays=zero_depth_rays,peer=other,reduce=False)
    if intervals:
        from . import curved_normal_interval_nodes
        mixed = c._stat(g,src,g.math('ABSOLUTE',
            g.math('LESS_THAN',c.named(g,'st_cg_start_width'),1e-7)-
            g.math('LESS_THAN',c.named(g,'st_cg_end_width'),1e-7)),'Max')
        interval_cap = g.math('MINIMUM',candidate,curved_normal_interval_nodes.cap(
            g,src,query,count,exact_mouths=all_intervals and exact_mouths,peer=other,reduce=False))
        candidate = interval_cap if all_intervals else c.choose(g,mixed,interval_cap,candidate)
    pairs = c._store(g,pairs,'_cb_cap',candidate)
    order = g.node('GeometryNodeSortElements','Minimum of every unchanged sample pair query')
    order.domain = 'POINT'
    g.bind(pairs,order.inputs['Geometry'])
    g.bind(query,order.inputs['Group ID'])
    g.bind(c.named(g,'_cb_cap'),order.inputs['Sort Weight'])
    cap = c._read(g,order.outputs['Geometry'],'_cb_cap',index*count)
    at = index+start if tiled else index
    if curvature_limits:
        cap = g.math('MINIMUM',cap,c._read(g,src,'st_cg_curvature_cap',at))
    own = c._read(g,src,'st_cg_nominal',at)
    depth,good = clearance._depth_query(g,src,at,own,cap,margin,directional=directional)
    result = g.setpos(c._line(g,rows),c._sample(g,src,g.position(),at,'FLOAT_VECTOR'))
    fields = (('owner','INT'),('t','FLOAT'),('nominal','FLOAT'),('distance','FLOAT'),
        ('length','FLOAT'),('start_width','FLOAT'),('end_width','FLOAT'),('normal','FLOAT_VECTOR'))
    if curvature_limits:
        fields += (('curvature_cap','FLOAT'),)
    if preserve_breaks:
        fields += (('break','BOOLEAN'),)
    for key,kind in fields:
        result = c._store(g,result,'st_cg_'+key,c._read(g,src,'st_cg_'+key,at,kind),kind)
    for key,value,kind in (('cap',cap,'FLOAT'),('depth',depth,'FLOAT'),('valid',good,'BOOLEAN')):
        result = c._store(g,result,'st_cg_'+key,value,kind)
    if tiled:
        g.bind(clearance.boundary._join(g,ri.outputs['Geometry'],result),ro.inputs['Geometry'])
        result = ro.outputs['Geometry']
    result = clearance.boundary._empty(g,result,valid)
    remove = g.node('GeometryNodeDeleteGeometry','Preserve the original loose point-table contract')
    remove.domain = 'EDGE';remove.mode = 'EDGE_FACE'
    g.bind(result,remove.inputs['Geometry'])
    result = remove.outputs['Geometry']
    valid = valid*c._stat(g,result,c.named(g,'st_cg_valid','BOOLEAN'))
    old = g.node('GeometryNodeGroup','Retain the existing evaluator beyond the batch memory limit')
    old.node_tree = clearance.allocate(preserve_breaks=preserve_breaks,exact_mouths=exact_mouths,
        mapped=True,curvature_limits=curvature_limits,directional=directional,intervals=intervals,
        all_intervals=all_intervals,zero_depth_rays=zero_depth_rays)
    for key in ('Geometry','Input Valid','Margin'):
        g.bind(inp.outputs[key],old.inputs[key])
    out = g.node('NodeGroupOutput')
    g.bind(c.choose(g,within,result,old.outputs['Geometry'],'GEOMETRY'),out.inputs['Geometry'])
    g.bind(c.choose(g,within,valid,old.outputs['Valid'],'BOOLEAN'),out.inputs['Valid'])
    return g.g


def replace_references(roots):
    """Opt in reachable directional kernels during a private asset build only.

    The conservative branch remains unchanged. Neither importing this module
    nor editing source geometry installs or runs Python replacement code.
    """
    import re
    prefix='Prochitecture Streets / Batched profile clearance v1'
    flags={'Knots':'preserve_breaks','Exact mouths':'exact_mouths',
        'Curvature limit':'curvature_limits','Directional':'directional',
        'Intervals':'intervals','All intervals':'all_intervals',
        'Directed static curb':'zero_depth_rays'}
    reachable=set();pending=list(roots)
    while pending:
        group=pending.pop()
        if group in reachable:continue
        reachable.add(group)
        pending.extend(n.node_tree for n in group.nodes if n.type=='GROUP' and n.node_tree)
    interface=lambda group:[(s.identifier,s.name,s.in_out,s.socket_type)
        for s in group.interface.items_tree if s.item_type=='SOCKET']
    replacements=[]
    for original in sorted(reachable,key=lambda g:g.name):
        if not original.name.startswith(prefix):continue
        name=re.sub(r'\.\d{3,}$','',original.name)
        tokens=name.split(' / ')[2:]
        if 'Tiled queries v1' in tokens or 'Directional' not in tokens:continue
        if set(tokens)-flags.keys():raise ValueError(('Unknown clearance variant',original.name))
        options={key:token in tokens for token,key in flags.items()}
        candidate=build(**options,tiled=True)
        if interface(original)!=interface(candidate):raise ValueError('Clearance interface changed')
        replacements.append(dict(original=original.name,candidate=candidate.name,
            options=options,users=original.users,max_pairs=TILE_PAIRS))
        original.user_remap(candidate)
    if not replacements:raise ValueError('No reachable directional clearance kernel replaced')
    return replacements
